#include <vector>
#include <CGAL/Arrangement_2.h>
#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <cg3/geometry/point2.h>

typedef CGAL::Exact_predicates_inexact_constructions_kernel Kernel;
typedef CGAL::Arrangement_2<Kernel> Arrangement2;
typedef cg3::Point2d Point2d;
typedef std::vector<Point2d> Polygon2d;

std::vector<Polygon2d> extractArrangementFaces(const Arrangement2& arr) {
    std::vector<Polygon2d> faces;

    // Iterate over all faces in the arrangement
    for (auto face_it = arr.faces_begin(); face_it != arr.faces_end(); ++face_it) {
        // Skip unbounded faces
        if (face_it->is_unbounded()) {
            continue;
        }

        // Traverse the outer boundary of the face
        Polygon2d polygon;
        auto circulator = face_it->outer_ccb();
        auto start = circulator;

        do {
            // Add the source point of the halfedge to the polygon
            polygon.push_back(Point2d(
                CGAL::to_double(circulator->source()->point().x()),
                CGAL::to_double(circulator->source()->point().y())
            ));
        } while (++circulator != start);

        // Add the polygon to the result
        faces.push_back(polygon);
    }

    return faces;
}

